import{_ as e,c as i,o as l,b2 as o}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"docs/guide/faq.md","filePath":"docs/guide/faq.md"}'),t={name:"docs/guide/faq.md"};function s(d,a,n,r,c,h){return l(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor vp-link" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="文档站看不到新页面" tabindex="-1">文档站看不到新页面？ <a class="header-anchor vp-link" href="#文档站看不到新页面" aria-label="Permalink to &quot;文档站看不到新页面？&quot;">​</a></h2><ol><li>必须在 <strong><code>docs</code> 目录</strong>执行 <code>pnpm dev</code>，不是 <code>quick-ui</code>。</li><li>修改 <code>nav.ts</code> / <code>sidebar.ts</code> 后<strong>重启</strong> dev 服务。</li><li>顶栏点击 <strong>指南 / 后端手册 / 前端手册 / 部署</strong> 进入对应侧栏。</li></ol><h2 id="登录返回-401-或-code-30002" tabindex="-1">登录返回 401 或 code 30002 <a class="header-anchor vp-link" href="#登录返回-401-或-code-30002" aria-label="Permalink to &quot;登录返回 401 或 code 30002&quot;">​</a></h2><ul><li><strong>30002</strong>：Client HMAC 失败。检查 <code>VITE_APP_CLIENT_ID</code>、<code>VITE_APP_CLIENT_SIGN_KEY</code> 与库表 <code>sys_oauth_client</code> 中明文 secret 一致。</li><li>确认请求 path 签名时<strong>不含 query</strong>。</li><li>多实例生产需 Redis，否则 nonce 防重放失效。</li></ul><h2 id="能登录但菜单为空" tabindex="-1">能登录但菜单为空 <a class="header-anchor vp-link" href="#能登录但菜单为空" aria-label="Permalink to &quot;能登录但菜单为空&quot;">​</a></h2><ul><li>用户是否分配角色；角色是否分配菜单。</li><li><code>getRouters</code> 接口是否 200；浏览器 Network 查看响应。</li></ul><h2 id="前端-api-404" tabindex="-1">前端 API 404 <a class="header-anchor vp-link" href="#前端-api-404" aria-label="Permalink to &quot;前端 API 404&quot;">​</a></h2><ul><li>后端是否已启动在 <strong>9992</strong>。</li><li><code>.env.development</code> 中 <code>VITE_APP_BASE_API=/dev-api</code> 是否与 <code>vite.config.js</code> proxy 一致。</li></ul><h2 id="flyway-启动失败" tabindex="-1">Flyway 启动失败 <a class="header-anchor vp-link" href="#flyway-启动失败" aria-label="Permalink to &quot;Flyway 启动失败&quot;">​</a></h2><ul><li>勿手工改 H2/MySQL 表不同步脚本。</li><li>检查 <code>db/migration</code> 是否冲突；开发可备份后删除 <code>./data/qcc</code> 重建（仅 dev）。</li></ul><h2 id="jasypt-启动报错" tabindex="-1">Jasypt 启动报错 <a class="header-anchor vp-link" href="#jasypt-启动报错" aria-label="Permalink to &quot;Jasypt 启动报错&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">-Djasypt.encryptor.password</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">=你的主密钥</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="oauth-授权页打不开" tabindex="-1">OAuth 授权页打不开 <a class="header-anchor vp-link" href="#oauth-授权页打不开" aria-label="Permalink to &quot;OAuth 授权页打不开&quot;">​</a></h2><ul><li>需已登录管理端；<code>authorize</code> 路由由菜单或直链进入。</li><li>白名单与 Client <code>api_path_patterns</code> 是否包含相关路径。</li></ul><h2 id="更多" tabindex="-1">更多 <a class="header-anchor vp-link" href="#更多" aria-label="Permalink to &quot;更多&quot;">​</a></h2><ul><li><a href="./../backend/modules/oauth2.html" class="vp-link">OAuth2 集成</a></li><li><a href="./../deploy/local-testing.html" class="vp-link">联调测试</a></li></ul>',17)])])}const _=e(t,[["render",s]]);export{u as __pageData,_ as default};
